// Compliance Report Dashboard Script
// Loads CSV, builds filter dropdowns, renders table, and shows detailed messages.

// Prefer compact JSON (generated by prepare_dashboard_json.py) then fall back to CSV.
const JSON_CANDIDATES = [
	//'docs/compliance-report.json',
	'compliance-report.json',
];
const CSV_CANDIDATES = [
	//'docs/compliance-report.csv',
	'compliance-report.csv',
];

const state = {
	rows: [],
	filtered: [],
	institution: '',
	source: '',
	search: '',
	lastUpdated: null
};

const els = {};

document.addEventListener('DOMContentLoaded', init);

function init(){
	cacheEls();
	loadCSV();
	bindEvents();
}

function cacheEls(){
	els.inst = document.getElementById('institutionFilter');
	els.source = document.getElementById('sourceFilter');
	els.search = document.getElementById('searchInput');
	els.clear = document.getElementById('clearFilters');
	els.status = document.getElementById('status');
	els.tbody = document.querySelector('#reportTable tbody');
	els.details = document.getElementById('detailsPanel');
	els.updateDate = document.getElementById('updateDate');
}

function loadCSV(){
	// First attempt JSON for speed
	setStatus('Loading data...');
	tryJson(0);

	function tryJson(i){
		if(i >= JSON_CANDIDATES.length){
			return tryCsv(0);
		}
		const path = JSON_CANDIDATES[i];
		fetch(path, { cache: 'no-store' }).then(r => {
			if(!r.ok) throw new Error(r.statusText);
			const lastModified = r.headers.get('last-modified');
			if(lastModified) state.lastUpdated = new Date(lastModified);
			return r.json();
		}).then(data => {
			if(!Array.isArray(data) || !data.length) throw new Error('Empty JSON');
			state.rows = data.map(enrichJsonRow);
			buildFilterOptions();			loadFiltersFromURL();			applyFilters();
			updateStatusAndDate(`Loaded ${state.rows.length} rows (JSON).`);
		}).catch(err => {
			console.warn('JSON load failed', path, err); tryJson(i+1);
		});
	}

	function tryCsv(i){
		if(i >= CSV_CANDIDATES.length){
			setStatus('Failed to locate compliance-report data');
			return;
		}
		const path = CSV_CANDIDATES[i];
		Papa.parse(path, {
			download: true,
			header: true,
			skipEmptyLines: true,
			dynamicTyping: true,
			complete: (results) => {
				if(!results.data || !results.data.length){
					console.warn('Empty result for', path, 'trying next');
					return tryCsv(i+1);
				}
				state.rows = results.data.map(enrichRow);
				buildFilterOptions();
				applyFilters();
				updateStatusAndDate(`Loaded ${state.rows.length} rows (CSV: ${path}).`);
			},
			error: (err) => { console.warn('Failed to load', path, err); tryCsv(i+1); }
		});
	}
}

function enrichRow(r){
	// Normalize multi-line message fields (cf medium/low/high priorities, wcrp_cordex_cmip6 likewise)
	const parseMsgs = (val) => (typeof val === 'string' && val.trim().length) ? val.trim().split(/\n+/).map(s=>s.trim()).filter(Boolean) : [];
	return {
		...r,
		cf_low_msgs: parseMsgs(r['cf:low_priorities']),
		cf_med_msgs: parseMsgs(r['cf:medium_priorities']),
		cf_high_msgs: parseMsgs(r['cf:high_priorities']),
		wcrp_low_msgs: parseMsgs(r['wcrp_cordex_cmip6:low_priorities']),
		wcrp_med_msgs: parseMsgs(r['wcrp_cordex_cmip6:medium_priorities']),
		wcrp_high_msgs: parseMsgs(r['wcrp_cordex_cmip6:high_priorities']),
		hasHigh: parseMsgs(r['cf:high_priorities']).length > 0 || parseMsgs(r['wcrp_cordex_cmip6:high_priorities']).length > 0
	};
}

function enrichJsonRow(r){
	// JSON already provides split arrays and count fields with simplified names.
	return {
		filename: r.filename,
		variable_id: r.variable_id,
		institution_id: r.institution_id,
		source_id: r.source_id,
		driving_source_id: r.driving_source_id,
		driving_experiment_id: r.driving_experiment_id,
		frequency: r.frequency,
		'cf:scored_points': r.cf_scored,
		'cf:possible_points': r.cf_possible,
		'cf:high_count': r.cf_high_count,
		'cf:medium_count': r.cf_medium_count,
		'cf:low_count': r.cf_low_count,
		'wcrp_cordex_cmip6:scored_points': r.wcrp_scored,
		'wcrp_cordex_cmip6:possible_points': r.wcrp_possible,
		'wcrp_cordex_cmip6:high_count': r.wcrp_high_count,
		'wcrp_cordex_cmip6:medium_count': r.wcrp_medium_count,
		'wcrp_cordex_cmip6:low_count': r.wcrp_low_count,
		cf_low_msgs: r.cf_low || [],
		cf_med_msgs: r.cf_med || [],
		cf_high_msgs: r.cf_high || [],
		wcrp_low_msgs: r.wcrp_low || [],
		wcrp_med_msgs: r.wcrp_med || [],
		wcrp_high_msgs: r.wcrp_high || [],
		hasHigh: !!r.hasHigh
	};
}

function buildFilterOptions(){
	const instVals = new Set();
	const srcVals = new Set();
	state.rows.forEach(r => {
		if(r.institution_id) instVals.add(r.institution_id);
		if(r.source_id) srcVals.add(r.source_id);
	});
	fillSelect(els.inst, [...instVals].sort());
	fillSelect(els.source, [...srcVals].sort());
}

function updateDependentFilters(){
	// Update source dropdown based on selected institution
	if(state.institution){
		const srcVals = new Set();
		state.rows.forEach(r => {
			if(r.institution_id === state.institution && r.source_id) srcVals.add(r.source_id);
		});
		fillSelect(els.source, [...srcVals].sort());
	} else {
		const srcVals = new Set();
		state.rows.forEach(r => {
			if(r.source_id) srcVals.add(r.source_id);
		});
		fillSelect(els.source, [...srcVals].sort());
	}
	
	// Update institution dropdown based on selected source
	if(state.source){
		const instVals = new Set();
		state.rows.forEach(r => {
			if(r.source_id === state.source && r.institution_id) instVals.add(r.institution_id);
		});
		fillSelect(els.inst, [...instVals].sort());
	} else {
		const instVals = new Set();
		state.rows.forEach(r => {
			if(r.institution_id) instVals.add(r.institution_id);
		});
		fillSelect(els.inst, [...instVals].sort());
	}
}

function fillSelect(sel, values){
	const current = sel.value;
	sel.innerHTML = '<option value="">All</option>' + values.map(v=>`<option value="${escapeHtml(v)}">${escapeHtml(v)}</option>`).join('');
	if(values.includes(current)) sel.value = current; else sel.value='';
}

function bindEvents(){
	els.inst.addEventListener('change', ()=> { 
		state.institution = els.inst.value; 
		updateDependentFilters();
		applyFilters();
		updateURL();
	});
	els.source.addEventListener('change', ()=> { 
		state.source = els.source.value; 
		updateDependentFilters();
		applyFilters();
		updateURL();
	});
	els.search.addEventListener('input', debounce(()=> { 
		state.search = els.search.value.trim().toLowerCase(); 
		applyFilters();
		updateURL();
	}, 150));
	els.clear.addEventListener('click', () => { 
		els.inst.value=''; 
		els.source.value=''; 
		els.search.value=''; 
		state.institution=''; 
		state.source=''; 
		state.search=''; 
		buildFilterOptions();
		applyFilters();
		updateURL();
	});
}

function applyFilters(){
	state.filtered = state.rows.filter(r => {
		if(state.institution && r.institution_id !== state.institution) return false;
		if(state.source && r.source_id !== state.source) return false;
		if(state.search && !String(r.filename).toLowerCase().includes(state.search)) return false;
		return true;
	});
	renderTable();
	setStatus(`${state.filtered.length} shown` + (state.filtered.length !== state.rows.length ? ` (of ${state.rows.length})` : ''));
}

function renderTable(){
	const frag = document.createDocumentFragment();
	state.filtered.forEach((r, idx) => {
		const tr = document.createElement('tr');
		if(r.hasHigh) tr.classList.add('high-priority');
		tr.innerHTML = `
			<td class="flag">${r.hasHigh ? '✖' : '✔'}</td>
			<td>${escapeHtml(basename(r.filename))}</td>
			<td>${escapeHtml(r.variable_id || '')}</td>
			<td>${escapeHtml(r.institution_id || '')}</td>
			<td>${escapeHtml(r.source_id || '')}</td>
			<td>${escapeHtml(r.driving_source_id || '')}</td>
			<td>${escapeHtml(r.driving_experiment_id || '')}</td>
			<td>${escapeHtml(r.frequency || '')}</td>
			<td>${scoreCell(r['cf:scored_points'], r['cf:possible_points'])}</td>
			<td>${scoreCell(r['wcrp_cordex_cmip6:scored_points'], r['wcrp_cordex_cmip6:possible_points'])}</td>
			<td>${issueCounts(r['cf:high_count'], r['cf:medium_count'], r['cf:low_count'])}</td>
			<td>${issueCounts(r['wcrp_cordex_cmip6:high_count'], r['wcrp_cordex_cmip6:medium_count'], r['wcrp_cordex_cmip6:low_count'])}</td>
		`;
		tr.classList.add('dashboard-row');
		tr.addEventListener('click', () => toggleDetails(idx));
		frag.appendChild(tr);

		// Details row (initially hidden)
		const detailsTr = document.createElement('tr');
		detailsTr.className = 'details-row';
		detailsTr.style.display = 'none';
		detailsTr.innerHTML = `<td colspan="12">${detailsContent(r)}</td>`;
		frag.appendChild(detailsTr);
	});
	els.tbody.innerHTML='';
	els.tbody.appendChild(frag);
}

function toggleDetails(idx){
	// There are 2 rows per dataset: data row, then details row
	const allRows = els.tbody.querySelectorAll('tr');
	for(let i=0; i<allRows.length; i+=2){
		const detailsRow = allRows[i+1];
		if(detailsRow && detailsRow.classList.contains('details-row')){
			if(i/2 === idx){
				// Toggle only the clicked row's details
				detailsRow.style.display = detailsRow.style.display === 'none' ? '' : 'none';
			} else {
				detailsRow.style.display = 'none';
			}
		}
	}
}

function detailsContent(r){
	return `
		<div class="inline-details">
			<h2>${escapeHtml(basename(r.filename))}</h2>
			<div style="font-size:0.95em;color:#567;margin-bottom:.3em;"><strong>Full path:</strong> <code>${escapeHtml(r.filename || '')}</code></div>
			<div><strong>institution_id:</strong> ${escapeHtml(r.institution_id||'')} &nbsp; <strong>source_id:</strong> ${escapeHtml(r.source_id||'')}</div>
			<div style="margin-top:.25rem;">
				${pill('CF', r['cf:scored_points'], r['cf:possible_points'])}
				${pill('WCRP CORDEX CMIP6', r['wcrp_cordex_cmip6:scored_points'], r['wcrp_cordex_cmip6:possible_points'])}
			</div>
			${messagesSection('CF High Priority', r.cf_high_msgs, 'high')}
			${messagesSection('CF Medium Priority', r.cf_med_msgs, 'medium')}
			${messagesSection('CF Low Priority', r.cf_low_msgs, 'low')}
			${messagesSection('WCRP CORDEX CMIP6 High Priority', r.wcrp_high_msgs, 'high')}
			${messagesSection('WCRP CORDEX CMIP6 Medium Priority', r.wcrp_med_msgs, 'medium')}
			${messagesSection('WCRP CORDEX CMIP6 Low Priority', r.wcrp_low_msgs, 'low')}
		</div>
	`;
}

function scoreCell(scored, possible){
	if(scored == null || possible == null) return '';
	const pct = possible ? (100 * scored / possible).toFixed(1) : '0.0';
	return `<span title="${scored}/${possible}">${pct}%</span>`;
}

function issueCounts(h, m, l){
	return `${h||0}/${m||0}/${l||0}`;
}

// showDetails is now unused

function pill(label, scored, possible){
	if(scored == null || possible == null) return '';
	const pct = possible ? (100 * scored / possible).toFixed(1) : '0.0';
	return `<span class="pill">${label} ${pct}%</span>`;
}

function messagesSection(title, list, level){
	if(!list || !list.length) return '';
	const cls = level ? `msgs-${level}` : '';
	return `<h3 class="pill ${level}">${escapeHtml(title)}</h3><ul class="msgs ${cls}">` + list.map(m=>`<li>${escapeHtml(m)}</li>`).join('') + '</ul>';
}

function setStatus(msg){
	if(els.status) els.status.textContent = msg;
}

function updateStatusAndDate(msg){
	setStatus(msg);
	if(els.updateDate){
		if(state.lastUpdated){
			const dateStr = state.lastUpdated.toLocaleString();
			els.updateDate.textContent = `Last updated: ${dateStr}`;
		}
	}
}

function loadFiltersFromURL(){
	const params = new URLSearchParams(window.location.search);
	const inst = params.get('institution');
	const src = params.get('source');
	const srch = params.get('search');
	
	if(inst && els.inst.querySelector(`option[value="${escapeHtml(inst)}"]`)){
		els.inst.value = inst;
		state.institution = inst;
	}
	if(src && els.source.querySelector(`option[value="${escapeHtml(src)}"]`)){
		els.source.value = src;
		state.source = src;
	}
	if(srch){
		els.search.value = srch;
		state.search = srch.toLowerCase();
	}
	
	if(inst || src || srch){
		updateDependentFilters();
	}
}

function updateURL(){
	const params = new URLSearchParams();
	if(state.institution) params.set('institution', state.institution);
	if(state.source) params.set('source', state.source);
	if(state.search) params.set('search', state.search);
	
	const newUrl = params.toString() 
		? `${window.location.pathname}?${params.toString()}`
		: window.location.pathname;
	window.history.replaceState({}, '', newUrl);
}

function basename(path){
	if(!path) return '';
	return String(path).split('/').slice(-1)[0];
}

function escapeHtml(str){
	return String(str ?? '').replace(/[&<>"']/g, s=>({ '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;','\'':'&#39;' }[s]));
}

function debounce(fn, wait){
	let t; return (...args)=>{ clearTimeout(t); t = setTimeout(()=>fn.apply(this,args), wait); };
}

// Optional: expose state for debugging
window.__reportState = state;
